corollary.derivative-no-simple-discontin.latex:
f \text{ differentiable on } [a,b]
\;\Rightarrow\;
f' \text{ has no simple discontinuities on } [a,b]

corollary.equal-derivatives-differ-by-co.latex:
f'(x) = g'(x) \;\forall\, x \in (a,b)
\;\Rightarrow\;
f(x) = g(x) + c

corollary.zero-derivative-constant.latex:
f'(x) = 0 \;\forall\, x \in (a,b)
\;\Rightarrow\;
f \text{ is constant on } (a,b)

definition.logarithmic-differentiation.latex:
\ln y = \ln f(x) \;\Rightarrow\;
\frac{y'}{y} = \frac{d}{dx}\bigl[\ln f(x)\bigr]
\;\Rightarrow\; y' = f(x) \cdot \frac{d}{dx}\bigl[\ln f(x)\bigr]

definition.partition.latex:
P = \{x_0, x_1, \ldots, x_n\}, \quad
a = x_0 \le x_1 \le \cdots \le x_n = b, \quad
\Delta x_i = x_i - x_{i-1}

definition.polar-coordinates.latex:
x = r\cos\theta,\quad y = r\sin\theta
\qquad
r^2 = x^2 + y^2,\quad \tan\theta = \frac{y}{x}

proposition.concavity-test.latex:
f''(x) > 0 \;\Rightarrow\; f \text{ concave up}
\qquad
f''(x) < 0 \;\Rightarrow\; f \text{ concave down}

proposition.increasing-decreasing-test.latex:
f'(x) > 0 \;\Rightarrow\; f \text{ increasing}
\qquad
f'(x) < 0 \;\Rightarrow\; f \text{ decreasing}

proposition.local-extremum-at-critical.latex:
f \text{ has local extremum at } c
\;\Rightarrow\;
c \text{ is a critical number of } f

theorem.alternating-series-test.latex:
b_{n+1} \le b_n \text{ and } \lim_{n\to\infty} b_n = 0
\;\Longrightarrow\;
\sum_{n=1}^{\infty} (-1)^{n-1} b_n \text{ converges}

theorem.comparison-test-series.latex:
0 \le a_n \le b_n \implies
\begin{cases}
\sum b_n \text{ conv.} \Rightarrow \sum a_n \text{ conv.}\\
\sum a_n \text{ div.} \Rightarrow \sum b_n \text{ div.}
\end{cases}

theorem.comparison-theorem-integrals.latex:
0 \le g(x) \le f(x) \implies
\begin{cases}
\int_a^\infty f\,dx \text{ conv.} \Rightarrow \int_a^\infty g\,dx \text{ conv.} \\
\int_a^\infty g\,dx \text{ div.} \Rightarrow \int_a^\infty f\,dx \text{ div.}
\end{cases}

theorem.extreme-value-theorem.latex:
f \text{ continuous on } [a,b]
\;\Rightarrow\;
\exists\, c,d \in [a,b] : f(d) \leq f(x) \leq f(c)\;\;\forall\, x \in [a,b]

theorem.finitely-discontinuous-integrabl.latex:
f \text{ bounded},\;
\#\{x : f \text{ discontinuous at } x\} < \infty,\;
\alpha \text{ continuous at each such } x
\implies f \in \mathscr{R}(\alpha)

theorem.integration-by-parts-riemann.latex:
F' = f \in \mathscr{R},\; G' = g \in \mathscr{R}
\implies
\int_a^b F g\,dx = F(b)G(b) - F(a)G(a) - \int_a^b f G\,dx

theorem.limit-comparison-test.latex:
\lim_{n \to \infty} \frac{a_n}{b_n} = c > 0
\;\Longrightarrow\;
\sum a_n \text{ and } \sum b_n
\text{ both converge or both diverge}

theorem.refinement-upper-lower-sums.latex:
P^* \supseteq P \implies
L(P,f,\alpha) \le L(P^*,f,\alpha) \;\text{and}\;
U(P^*,f,\alpha) \le U(P,f,\alpha)

theorem.rolles-theorem.latex:
f \in C[a,b],\; f \text{ diff. on } (a,b),\; f(a)=f(b)
\;\Rightarrow\;
\exists\, c \in (a,b) : f'(c) = 0

theorem.sequential-characterization-func.latex:
\lim_{x \to p} f(x) = q \;\iff\;
\lim_{n \to \infty} f(p_n) = q \text{ for every } \{p_n\} \subset E
\text{ with } p_n \neq p,\; p_n \to p
